import {createController,canonical,fixed,fraction} from './core.mjs';
const messages={"en":{"title":"Flex Shrink Distribution Explorer","description":"Understand proportional shrink, minimum-width freezes and remaining overflow in a finite empty-box Flexbox model.","eyebrow":"CSS GEOMETRY · FLEX SHRINK","edit":"1. Configure the row","view":"2. Follow the distribution","count":"Item count","c":"Container inner width C (px)","b":"Basis (px)","s":"Shrink factor","m":"Minimum width (px)","item":"Item","generate":"Generate","reset":"Reset","defaults":"Defaults example","freeze":"Minimum freeze example","select":"Select CSS","language":"繁體中文","units":"C: 40–1200 px; basis/minimum: 0–1200 px; shrink: 0–4. Up to two decimals, no signs or leading zeros. Raw limit 64 characters. Values are CSS pixels.","privacy":"Only synthetic numeric inputs, calculated in this page. No upload, persistence, clipboard API, download or permission request.","empty":"No result yet. Try Minimum freeze, then Generate. Inputs alone do not calculate a new result.","scope":"A deliberately small model","scopeText":"3–6 empty, non-replaced boxes; horizontal-tb/ltr, row/nowrap, grow 0, explicit px basis/minimum, content-box and zero margin/padding/border/gap. No automatic minimum, intrinsic content, wrapping, percentages or full-browser simulation.","manual":"Select CSS, then use your operating system’s Copy command. Nothing is copied automatically.","boot":"JavaScript is unavailable or unsupported. Read the explanation, but no result can be generated.","branch":"Branch","shrink":"Shrink","no-growth":"No growth (grow factors are zero)","f0":"Initial free space F₀","residual":"Exact residual C − total used width","overflowValue":"Right overflow","fit":"Exact fit","unused":"Unused space at the right","overflowNote":"Overflow remains at the right; it is not normalized away.","rounded":"Decimals marked ≈ are rounded to two places. Exact fractions decide signs and iteration branches.","final":"Requested versus used widths","id":"Item","requested":"Basis / shrink / minimum","hypothetical":"H = max(basis, minimum)","reason":"Initial freeze reason","used":"Used width ≈ / exact","zero":"Zero-width item (see external legend)","active":"Active","grow-zero":"Zero grow factor","zero-shrink":"Zero shrink factor","minimum-above-basis":"Minimum exceeds basis","both":"Zero shrink and minimum exceeds basis","rounds":"Shrink rounds","noRounds":"No shrink rounds","round":"Round","activeIds":"Active items","newly":"Newly frozen","tentative":"Tentative → limited widths","zeroWeight":"Zero contribution: active bases are zero; no division by zero.","css":"Requested CSS","warning":"Use N empty direct child blocks with class=item inside class=flex-demo, with no other children or author CSS. Output keeps the requested values; it does not force calculated widths. Other content or cascade can change behavior.","preview":"Native empty-box preview. Scroll inside the frame; labels stay outside to avoid changing intrinsic widths.","legend":"External item legend","skip":"Skip to tool","footer":"EMPTY BOXES · EXACT FRACTIONS · MANUAL SELECTION","status":{"dirty":"Inputs changed. Generate to replace the result.","invalid":"Fix the marked fields. No result is available.","generated":"Result generated. Inspect exact residual and round details.","overflow":"Result generated with remaining overflow. See the exact residual.","selected":"CSS selected. Use your operating system’s Copy command.","manual":"Automatic selection unavailable. Select the CSS manually.","internal":"Result unavailable: a bounded model check failed. Reset the form."},"errors":{"syntax":"Use an unsigned decimal with at most two fractional digits and no leading zeros.","range":"Outside the stated supported range.","length":"More than 64 raw characters; shorten this value.","schema":"Use 3–6 complete items, or Reset."}},"zh-Hant":{"title":"Flex Shrink 分配解說器","description":"理解空白 Flexbox 模型中的比例縮減、最小寬度凍結與剩餘溢出。","eyebrow":"CSS 幾何 · FLEX SHRINK","edit":"1. 設定單列項目","view":"2. 追蹤分配過程","count":"項目數量","c":"容器內寬 C（px）","b":"基礎寬度（px）","s":"縮減因子","m":"最小寬度（px）","item":"項目","generate":"產生結果","reset":"重設","defaults":"預設範例","freeze":"最小值凍結範例","select":"選取 CSS","language":"English","units":"C：40–1200 px；基礎／最小寬度：0–1200 px；縮減因子：0–4。最多兩位小數，不接受正負號或前導零。原始輸入上限 64 字元。單位為 CSS 像素。","privacy":"僅在本頁處理數字。不傳送、不保存、不呼叫剪貼簿、不下載，也不要求額外權限。","empty":"尚未產生結果。可先選「最小值凍結範例」，再產生結果。修改輸入不會自動重新計算。","scope":"刻意限縮的模型","scopeText":"3–6 個空白非替換方塊；horizontal-tb/ltr、row/nowrap、grow 為 0、明確 px basis／minimum、content-box，margin/padding/border/gap 皆為零。不含自動最小尺寸、內容測量、換行、百分比或完整瀏覽器模擬。","manual":"選取 CSS 後，請使用作業系統的複製指令。本工具不會自動複製。","boot":"JavaScript 未啟用或瀏覽器不支援。仍可閱讀說明，但無法產生結果。","branch":"計算分支","shrink":"縮減","no-growth":"不成長（grow 因子皆為零）","f0":"初始自由空間 F₀","residual":"精確剩餘空間 C − 使用寬度總和","overflowValue":"右側溢出","fit":"精確填滿","unused":"右側保留未使用空間","overflowNote":"右側仍有溢出，不會強制正規化消除。","rounded":"≈ 小數顯示至兩位。符號與每輪分支皆由精確分數決定。","final":"指定值與使用寬度","id":"項目","requested":"基礎／縮減／最小","hypothetical":"H = max（基礎，最小）","reason":"初始凍結原因","used":"使用寬度 ≈／精確值","zero":"零寬度項目（見外側圖例）","active":"尚未凍結","grow-zero":"grow 因子為零","zero-shrink":"縮減因子為零","minimum-above-basis":"最小寬度大於基礎寬度","both":"縮減為零且最小值大於基礎","rounds":"縮減迴圈","noRounds":"沒有縮減迴圈","round":"第幾輪","activeIds":"活動項目","newly":"本輪新凍結","tentative":"暫定 → 限制後寬度","zeroWeight":"零貢獻：活動項目的基礎寬度皆為零，不進行除零。","css":"指定值 CSS","warning":"需要 class=flex-demo 容器與 N 個 class=item 的空白直接子方塊，沒有其他子內容或作者樣式。CSS 保留指定值，不強制計算後寬度；其他內容或層疊樣式可能改變結果。","preview":"瀏覽器空白方塊預覽。請在框內捲動；標籤置於外側，避免改變內容尺寸。","legend":"外側項目圖例","skip":"跳到工具","footer":"空白方塊 · 精確分數 · 手動選取","status":{"dirty":"輸入已改變，請重新產生結果。","invalid":"請修正標記欄位，尚無可用結果。","generated":"結果已產生，請查看精確剩餘空間與逐輪明細。","overflow":"結果已產生，仍有溢出；請查看精確剩餘空間。","selected":"已選取 CSS，請使用作業系統的複製指令。","manual":"無法自動選取，請手動選取 CSS 文字。","internal":"有限模型檢查失敗，無法產生結果，請重設。"},"errors":{"syntax":"請使用最多兩位小數的無號十進位數字，不含前導零。","range":"超出上述支援範圍。","length":"原始輸入超過 64 字元，請縮短。","schema":"請使用 3–6 個完整項目，或重設。"}}};
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const numberText=x=>'≈ '+fixed(x)+' / '+fraction(x);
function start(){
 let previousCount=0,previousModel=null,previousLang=null,controller;
 const inputField=(id,label)=>{const d=el('div');d.className='field';const l=el('label',label);l.id='label-'+id;l.htmlFor=id;const input=el('input');input.id=id;input.type='text';input.inputMode='decimal';input.autocomplete='off';input.spellcheck=false;input.setAttribute('aria-describedby','units error-'+id);const error=el('span');error.id='error-'+id;error.className='error';d.append(l,input,error);input.addEventListener('input',()=>controller.edit(id,input.value));input.addEventListener('compositionstart',()=>controller.composition(true));input.addEventListener('compositionend',()=>{controller.composition(false);controller.edit(id,input.value);});return d;};
 controller=createController({lang:document.documentElement.lang,focus:id=>$(id).focus(),clear:()=>{$('css').value='';},render(s){
  const m=messages[s.lang];document.documentElement.lang=s.lang;document.title=m.title+' · GlossQuote Labs';document.querySelector('meta[name=description]').content=m.description;
  for(const e of document.querySelectorAll('[data-msg]'))e.textContent=m[e.dataset.msg];$('language').textContent=m.language;$('language').lang=s.lang==='en'?'zh-Hant':'en';$('home').href=s.lang==='en'?'https://glossquote.com/en/index.html':'https://glossquote.com/index.html';
  if(previousCount!==s.raw.items.length){const nodes=s.raw.items.map((_,i)=>{const fieldset=el('fieldset');fieldset.className='item-fields';const legend=el('legend',m.item+' '+(i+1));legend.id='legend-'+i;fieldset.append(legend);const grid=el('div');grid.className='item-grid';for(const k of ['b','s','m'])grid.append(inputField(k+i,m[k]));fieldset.append(grid);return fieldset;});$('items').replaceChildren(...nodes);previousCount=s.raw.items.length;}
  $('count').value=String(s.raw.items.length);const values=[['c',s.raw.c],...s.raw.items.flatMap((v,i)=>['b','s','m'].map(k=>[k+i,v[k]]))];
  for(const[id,value]of values){if($(id).value!==value)$(id).value=value;const label=id==='c'?m.c:m.item+' '+(+id.slice(1)+1)+' · '+m[id[0]];$('label-'+id).textContent=label;const error=s.errors.find(e=>e.id===id);$(id).setAttribute('aria-invalid',String(!!error));$('error-'+id).textContent=error?m.errors[error.code]:'';}
  s.raw.items.forEach((_,i)=>$('legend-'+i).textContent=m.item+' '+(i+1));$('error-count').textContent=s.errors.find(e=>e.id==='count')?m.errors.schema:'';
  $('errors').replaceChildren(...s.errors.map(e=>{const li=el('li'),a=el('a',(e.id==='count'?m.count:$('label-'+e.id).textContent)+': '+m.errors[e.code]);a.href='#'+e.id;a.addEventListener('click',event=>{event.preventDefault();$(e.id).focus();});li.append(a);return li;}));
  $('status').textContent=m.status[s.status]||'';$('empty').hidden=!!s.model;$('result').hidden=!s.model;$('select').disabled=!s.model;
  if(!s.model){$('demo').replaceChildren();$('demo').style.width='';$('final-rows').replaceChildren();$('round-details').replaceChildren();$('summary').replaceChildren();previousModel=null;return;}
  if(previousModel!==s.model||previousLang!==s.lang){const model=s.model,summary=[m.branch+': '+m[model.branch],m.f0+': '+numberText(model.F0),m.residual+': '+numberText(model.residual),model.residual.n<0n?m.overflowNote:model.residual.n>0n?m.unused:m.fit,m.overflowValue+': '+numberText(model.overflow)];$('summary').replaceChildren(...summary.map(x=>el('p',x)));
   $('final-rows').replaceChildren(...model.items.map((x,i)=>{const tr=el('tr'),th=el('th',m.item+' '+x.id);th.scope='row';const v=model.value.items[i];tr.append(th,el('td',[canonical(v.b),canonical(v.s),canonical(v.m)].join(' / ')),el('td',numberText(model.H[i])),el('td',m[model.reasons[i]]),el('td',numberText(model.targets[i])+(model.targets[i].n===0n?' — '+m.zero:'')));return tr;}));
   $('round-details').replaceChildren(...(model.rounds.length?model.rounds.map((r,i)=>{const section=el('section');section.className='round';section.append(el('h4',m.round+' '+(i+1)),el('p',m.activeIds+': '+r.active.join(', ')+' · '+m.newly+': '+r.newly.join(', ')));const dl=el('dl');for(const[k,v]of [['R',r.R],['R*',r.Rstar],['A',r.A],['D',r.D]])dl.append(el('dt',k),el('dd',numberText(v)));section.append(dl,el('p',m.tentative));const list=el('ul');r.active.forEach((id,j)=>list.append(el('li',m.item+' '+id+': '+numberText(r.tentative[j])+' → '+numberText(r.limited[j]))));section.append(list);if(r.zeroWeight)section.append(el('p',m.zeroWeight));return section;}):[el('p',m.noRounds)]));
   $('demo').style.width=canonical(model.value.c)+'px';$('demo').replaceChildren(...model.value.items.map((v,i)=>{const item=el('div');item.className='item color-'+i;item.style.flexGrow='0';item.style.flexShrink=canonical(v.s);item.style.flexBasis=canonical(v.b)+'px';item.style.minWidth=canonical(v.m)+'px';return item;}));
   $('item-legend').replaceChildren(...model.items.map((x,i)=>{const li=el('li',m.item+' '+x.id+(model.targets[i].n===0n?' — '+m.zero:''));li.className='legend-'+i;return li;}));
   if($('css').value!==model.css)$('css').value=model.css;
  }previousModel=s.model;previousLang=s.lang;
 }});
 $('c').addEventListener('input',()=>controller.edit('c',$('c').value));$('c').addEventListener('compositionstart',()=>controller.composition(true));$('c').addEventListener('compositionend',()=>{controller.composition(false);controller.edit('c',$('c').value);});
 $('count').addEventListener('change',()=>controller.count($('count').value));$('form').addEventListener('submit',e=>{e.preventDefault();controller.submit();});$('reset').addEventListener('click',()=>controller.reset());$('defaults').addEventListener('click',()=>controller.example());$('freeze').addEventListener('click',()=>controller.example(true));$('language').addEventListener('click',()=>controller.language());$('select').addEventListener('click',()=>controller.select(()=>{$('css').focus();$('css').select();if($('css').selectionEnd-$('css').selectionStart!==$('css').value.length)throw Error('selection');}));
 window.addEventListener('pagehide',()=>controller.leave());window.addEventListener('pageshow',e=>{if(e.persisted)controller.restore();});for(const id of ['count','generate','reset','defaults','freeze','language'])$(id).disabled=false;$('boot-status').hidden=true;
}
if(typeof BigInt==='function'&&typeof Object.hasOwn==='function')try{start();}catch{document.getElementById('boot-status').hidden=false;for(const b of document.querySelectorAll('button'))b.disabled=true;document.getElementById('result').hidden=true;}
